function Counter() {
  const [count, setCount] = useState(0);

  // This effect depends on count
  useEffect(() => {
    document.title = `Count: ${count}`;
    // count is used, so it MUST be in dependencies
  }, [count]); // ✅ Correct

  return <button onClick={() => setCount(count + 1)}>+</button>;
}

// ❌ INFINITE LOOP - new object every render
function Bad() {
  const config = { url: '/api' }; // New object each render!

  useEffect(() => {
    fetch(config.url);
  }, [config]); // Effect sees new object, runs again!
}

// ✅ SOLUTION 1: Use primitive values
function Good() {
  const url = '/api';

  useEffect(() => {
    fetch(url);
  }, [url]); // String is compared by value
}

// ✅ SOLUTION 2: Move object outside component
const config = { url: '/api' }; // Created once
function Good() {
  useEffect(() => {
    fetch(config.url);
  }, [config]); // Same reference every time
}
